1	package com.example.starter.service;
2	
3	import com.example.starter.dao.AlertRepository;
4	import com.example.starter.dao.AlertRow;
5	import com.example.starter.dao.CatalogRepository;
6	import com.example.starter.dao.DiveEventRepository;
7	import com.example.starter.dao.DiveRepository;
8	import com.example.starter.dao.DiveRow;
9	import com.example.starter.dao.LedgerRow;
10	import com.example.starter.dao.PlanRepository;
11	import com.example.starter.dao.PlanRow;
12	import com.example.starter.dao.RecordRepository;
13	import com.example.starter.dao.RecordRow;
14	import com.example.starter.domain.EventTypes;
15	import com.example.starter.domain.Phase;
16	import com.example.starter.web.ApiException;
17	import com.example.starter.web.dto.ApplyRequest;
18	import com.example.starter.web.dto.ApplyResult;
19	import com.example.starter.web.dto.CloseRequest;
20	import com.example.starter.web.dto.PlanRequest;
21	import com.example.starter.web.dto.RecordRequest;
22	import com.example.starter.web.dto.SurfaceRequest;
23	import com.example.starter.web.dto.VitalsRequest;
24	import org.springframework.dao.DuplicateKeyException;
25	import org.springframework.stereotype.Service;
26	
27	import java.math.BigDecimal;
28	import java.sql.Timestamp;
29	import java.time.Clock;
30	import java.time.Duration;
31	import java.time.Instant;
32	import java.util.ArrayList;
33	import java.util.LinkedHashMap;
34	import java.util.List;
35	import java.util.Map;
36	
37	/**
38	 * 潜水作业核心领域服务：申请→方案→执行→出水观察→结案。
39	 *
40	 * <p>全部操作经 {@link IdempotencyService} 在单事务内执行业务并登记幂等台账。</p>
41	 */
42	@Service
43	public class DiveService {
44	
45	    /** 下潜/出水速率上限，米/分钟；恰 18 合格，大于 18 告警。 */
46	    public static final int RATE_LIMIT = 18;
47	    /** 同一潜水员 24 小时（UTC）累计水下时间上限，分钟；恰 6 小时合法。 */
48	    public static final int MAX_BOTTOM_MIN_24H = 360;
49	    /** 出水后观察时长，小时；恰满 2 小时方可结案。 */
50	    public static final Duration OBSERVATION = Duration.ofHours(2);
51	
52	    private final DiveRepository dives;
53	    private final PlanRepository plans;
54	    private final RecordRepository records;
55	    private final AlertRepository alerts;
56	    private final DiveEventRepository events;
57	    private final CatalogRepository catalog;
58	    private final IdempotencyService idempotency;
59	    private final Clock clock;
60	
61	    public DiveService(DiveRepository dives, PlanRepository plans, RecordRepository records,
62	                       AlertRepository alerts, DiveEventRepository events,
63	                       CatalogRepository catalog, IdempotencyService idempotency, Clock clock) {
64	        this.dives = dives;
65	        this.plans = plans;
66	        this.records = records;
67	        this.alerts = alerts;
68	        this.events = events;
69	        this.catalog = catalog;
70	        this.idempotency = idempotency;
71	        this.clock = clock;
72	    }
73	
74	    // ------------------------------------------------------------------
75	    // 1. 作业申请
76	    // ------------------------------------------------------------------
77	
78	    public IdempotencyService.Outcome<ApplyResult> apply(ApplyRequest req) {
79	        if (req.diverACode().equals(req.diverBCode())) {
80	            throw new ApiException(400, "潜水两人一组必须为两名不同潜水员");
81	        }
82	        if (!catalog.diverExists(req.diverACode()) || !catalog.diverExists(req.diverBCode())) {
83	            throw new ApiException(400, "潜水员不在合成名册中: " + req.diverACode() + "/" + req.diverBCode());
84	        }
85	        String teamKey = teamKey(req.diverACode(), req.diverBCode());
86	        Map<String, Object> fields = new LinkedHashMap<>();
87	        fields.put("diverACode", req.diverACode());
88	        fields.put("diverBCode", req.diverBCode());
89	        fields.put("plannedDepthM", req.plannedDepthM());
90	        fields.put("plannedBottomMin", req.plannedBottomMin());
91	
92	        return idempotency.execute(req.requestId(), "APPLY", fields, () -> {
93	            Instant now = Instant.now(clock);
94	            String fingerprint = com.example.starter.support.Fingerprints.sha256(
95	                    new java.util.TreeMap<>(fields) {{
96	                        put("requestId", req.requestId());
97	                    }});
98	            DiveRow row = new DiveRow(req.requestId(), fingerprint, teamKey, teamKey,
99	                    req.diverACode(), req.diverBCode(), req.plannedDepthM(), req.plannedBottomMin(),
100	                    "APPLIED", 0, null, false, null, now, now);
101	            // 唯一冲突（同 requestId 并发，或同组 active_team_slot 占用）原样抛出，
102	            // 由幂等层在胜方事务提交后区分：等到同 requestId 台账则重放/409，等不到则同组 409
103	            dives.insert(row);
104	            return IdempotencyService.FirstResult.created(new ApplyResult(
105	                    req.requestId(), teamKey, req.diverACode(), req.diverBCode(),
106	                    req.plannedDepthM(), req.plannedBottomMin(), "APPLIED", false));
107	        });
108	    }
109	
110	    // ------------------------------------------------------------------
111	    // 2. 减压方案（查表 NDL，可变更；旧方案与旧记录同事务冻结）
112	    // ------------------------------------------------------------------
113	
114	    public IdempotencyService.Outcome<ApplyResult.PlanResult> plan(PlanRequest req) {
115	        requireDive(req.diveRequestId());
116	        Integer ndl = catalog.findNdlMinutes(req.depthM());
117	        if (ndl == null) {
118	            throw new ApiException(400, "合成减压表中无深度 " + req.depthM() + " 米的条目");
119	        }
120	        if (req.bottomMin() > ndl) {
121	            throw new ApiException(422, "底时间 " + req.bottomMin() + " 分钟超过 " + req.depthM()
122	                    + " 米免减压极限 " + ndl + " 分钟");
123	        }
124	        Map<String, Object> fields = new LinkedHashMap<>();
125	        fields.put("diveRequestId", req.diveRequestId());
126	        fields.put("depthM", req.depthM());
127	        fields.put("bottomMin", req.bottomMin());
128	
129	        return idempotency.execute(req.requestId(), "PLAN", fields, () -> {
130	            // 动作内重读最新状态：仅首次受理执行，重放不进入，不会因潜次已流转而误判
131	            DiveRow latest = requireDive(req.diveRequestId());
132	            if ("SURFACED".equals(latest.status()) || "CLOSED".equals(latest.status())
133	                    || "FROZEN".equals(latest.status())) {
134	                throw new ApiException(409, "潜次已进入" + latest.status() + "阶段，减压方案不可变更");
135	            }
136	            Instant now = Instant.now(clock);
137	            int newVersion = latest.currentPlanVersion() + 1;
138	            int frozenOld = 0;
139	            if (newVersion > 1) {
140	                // 方案变更：旧方案、其全部已生成记录与台账在同一事务内冻结/清退，
141	                // 后续记录只能挂在新版本，杜绝沿用旧方案记录
142	                frozenOld = plans.freezeAll(req.diveRequestId());
143	                records.freezeByDive(req.diveRequestId());
144	                records.deleteLedgerByDive(req.diveRequestId());
145	                events.insert(req.diveRequestId(), EventTypes.PLAN_FROZEN,
146	                        "方案变更：冻结 v" + (newVersion - 1) + " 及其水下记录", now);
147	            }
148	            String profileJson = Profiles.buildJson(req.depthM(), req.bottomMin());
149	            String planFingerprint = com.example.starter.support.Fingerprints.sha256(
150	                    new java.util.TreeMap<>(fields) {{
151	                        put("requestId", req.requestId());
152	                    }});
153	            plans.insert(new com.example.starter.dao.PlanRow(null, req.diveRequestId(),
154	                    newVersion, req.depthM(), req.bottomMin(), ndl, RATE_LIMIT, RATE_LIMIT,
155	                    profileJson, false, planFingerprint, now));
156	            plans.bumpDiveVersion(req.diveRequestId(), newVersion, now);
157	
158	            List<ApplyResult.Segment> segments = List.of(
159	                    new ApplyResult.Segment(Phase.DESCENT.name(), 0, req.depthM(),
160	                            (int) Math.ceil(req.depthM() / (double) RATE_LIMIT), RATE_LIMIT),
161	                    new ApplyResult.Segment(Phase.BOTTOM.name(), req.depthM(), req.depthM(),
162	                            req.bottomMin(), RATE_LIMIT),
163	                    new ApplyResult.Segment(Phase.ASCENT.name(), req.depthM(), 0,
164	                            (int) Math.ceil(req.depthM() / (double) RATE_LIMIT), RATE_LIMIT));
165	            return IdempotencyService.FirstResult.created(new ApplyResult.PlanResult(
166	                    req.diveRequestId(), newVersion, req.depthM(), req.bottomMin(), ndl,
167	                    RATE_LIMIT, segments, frozenOld, false));
168	        });
169	    }
170	
171	    // ------------------------------------------------------------------
172	    // 3. 水下记录（单人不生效；同阶段成对才生效：复算速率、告警、入台账、6 小时校验）
173	    // ------------------------------------------------------------------
174	
175	    public IdempotencyService.Outcome<ApplyResult.RecordResult> record(RecordRequest req) {
176	        req.validate();
177	        requireDive(req.diveRequestId());
178	
179	        Map<String, Object> fields = new LinkedHashMap<>();
180	        fields.put("diveRequestId", req.diveRequestId());
181	        fields.put("diverCode", req.diverCode());
182	        fields.put("phase", req.phase());
183	        fields.put("fromDepthM", req.fromDepthM());
184	        fields.put("toDepthM", req.toDepthM());
185	        fields.put("durationMin", req.durationMin());
186	        fields.put("eventTime", req.eventTime());
187	
188	        return idempotency.execute(req.requestId(), "RECORD", fields, () -> {
189	            // 动作内重读潜次与当前方案：首次受理才执行，重放直接返回首次结果
190	            DiveRow dive = requireDive(req.diveRequestId());
191	            if (dive.currentPlanVersion() == 0) {
192	                throw new ApiException(409, "潜次尚无减压方案，不能提交水下记录");
193	            }
194	            if (!req.diverCode().equals(dive.diverACode()) && !req.diverCode().equals(dive.diverBCode())) {
195	                throw new ApiException(403, "潜水员 " + req.diverCode() + " 不属于本潜次潜水组");
196	            }
197	            if (!"PLANNED".equals(dive.status()) && !"DIVING".equals(dive.status())) {
198	                throw new ApiException(409, "潜次处于 " + dive.status() + " 阶段，不能提交水下记录");
199	            }
200	            PlanRow plan = plans.getVersion(req.diveRequestId(), dive.currentPlanVersion());
201	            validatePhaseShape(req, plan);
202	
203	            Instant now = Instant.now(clock);
204	            BigDecimal rate = RecordRepository.rateOf(req.phase(), req.fromDepthM(),
205	                    req.toDepthM(), req.durationMin());
206	            RecordRow row = new RecordRow(null, req.diveRequestId(), plan.version(),
207	                    req.diverCode(), req.phase(), req.fromDepthM(), req.toDepthM(),
208	                    req.durationMin(), rate, false, false, null, req.eventTime(), now);
209	            long recordId;
210	            try {
211	                recordId = records.insert(row);
212	            } catch (DuplicateKeyException dup) {
213	                throw new ApiException(409, "潜水员 " + req.diverCode() + " 在方案 v"
214	                        + plan.version() + " 的 " + req.phase() + " 阶段记录已存在");
215	            }
216	
217	            boolean effective = false;
218	            String pairedWith = null;
219	            boolean speedAlert = false;
220	            int cumulative = 0;
221	            String newStatus = dive.status();
222	
223	            RecordRow peer = records.findPairPeer(req.diveRequestId(), plan.version(),
224	                    req.phase(), req.diverCode()).orElse(null);
225	            if (peer != null) {
226	                // 两人同阶段成对：同事务内同时生效
227	                records.markPaired(recordId, peer.id());
228	                records.markPaired(peer.id(), recordId);
229	                effective = true;
230	                pairedWith = peer.diverCode();
231	                newStatus = "DIVING";
232	
233	                if (Phase.BOTTOM.name().equals(req.phase())) {
234	                    cumulative = settleBottomPair(dive, plan,
235	                            records.getById(recordId), records.getById(peer.id()), now);
236	                } else {
237	                    speedAlert = settleSpeedPair(dive, plan,
238	                            records.getById(recordId), records.getById(peer.id()), now);
239	                }
240	                dives.updateStatus(req.diveRequestId(), newStatus, now);
241	            }
242	
243	            return IdempotencyService.FirstResult.ok(new ApplyResult.RecordResult(
244	                    req.diveRequestId(), plan.version(), req.diverCode(), req.phase(),
245	                    rate.toPlainString(), speedAlert, effective, pairedWith, newStatus,
246	                    cumulative, false));
247	        });
248	    }
249	
250	    /** 成对 BOTTOM：逐人做 24 小时累计 6 小时校验（恰 6 合法），通过后两人同事务入账。 */
251	    private int settleBottomPair(DiveRow dive, PlanRow plan, RecordRow mine, RecordRow peer,
252	                                 Instant now) {
253	        Instant windowEnd = !mine.eventTimeUtc().isBefore(peer.eventTimeUtc())
254	                ? mine.eventTimeUtc() : peer.eventTimeUtc();
255	        int myCumulative = checkCumulative(mine, windowEnd);
256	        int peerCumulative = checkCumulative(peer, windowEnd);
257	        insertLedgerIfAbsent(dive, plan, mine, now);
258	        insertLedgerIfAbsent(dive, plan, peer, now);
259	        return Math.max(myCumulative, peerCumulative);
260	    }
261	
262	    /** 校验某潜水员窗口内累计加本次不超过 6 小时；返回含本次的累计分钟。 */
263	    private int checkCumulative(RecordRow bottom, Instant windowEnd) {
264	        Timestamp start = Timestamp.from(windowEnd.minus(Duration.ofHours(24)));
265	        Timestamp end = Timestamp.from(windowEnd);
266	        int existed = records.sumBottomMinutes(bottom.diverCode(), start, end);
267	        int total = existed + bottom.durationMin();
268	        if (total > MAX_BOTTOM_MIN_24H) {
269	            throw new ApiException(422, "潜水员 " + bottom.diverCode() + " 24 小时内累计水下时间 "
270	                    + total + " 分钟超过上限 " + MAX_BOTTOM_MIN_24H + " 分钟（6 小时），记录回滚不生效");
271	        }
272	        return total;
273	    }
274	
275	    private void insertLedgerIfAbsent(DiveRow dive, PlanRow plan, RecordRow bottom, Instant now) {
276	        if (!records.ledgerExists(dive.requestId(), plan.version(), bottom.diverCode())) {
277	            records.insertLedger(new LedgerRow(null, bottom.diverCode(), dive.requestId(),
278	                    plan.version(), bottom.durationMin(), bottom.eventTimeUtc()));
279	        }
280	    }
281	
282	    /** 成对下潜/上升：逐人复算速率，大于 18 落告警（恰 18 合格），返回本人是否告警。 */
283	    private boolean settleSpeedPair(DiveRow dive, PlanRow plan, RecordRow mine, RecordRow peer,
284	                                    Instant now) {
285	        raiseAlertIfOverspeed(dive, plan, mine, now);
286	        raiseAlertIfOverspeed(dive, plan, peer, now);
287	        return mine.rateMMin().compareTo(BigDecimal.valueOf(RATE_LIMIT)) > 0;
288	    }
289	
290	    private void raiseAlertIfOverspeed(DiveRow dive, PlanRow plan, RecordRow rec, Instant now) {
291	        if (rec.rateMMin().compareTo(BigDecimal.valueOf(RATE_LIMIT)) > 0) {
292	            alerts.insert(new AlertRow(null, dive.requestId(), plan.version(), rec.diverCode(),
293	                    rec.phase(), rec.rateMMin(), rec.eventTimeUtc(), now));
294	        }
295	    }
296	
297	    private void validatePhaseShape(RecordRequest req, PlanRow plan) {
298	        int d = plan.depthM();
299	        switch (req.phase()) {
300	            case "DESCENT" -> {
301	                if (req.fromDepthM() != 0 || req.toDepthM() != d) {
302	                    throw new ApiException(400, "DESCENT 深度须为 0→" + d + " 米");
303	                }
304	            }
305	            case "BOTTOM" -> {
306	                if (req.fromDepthM() != d || req.toDepthM() != d) {
307	                    throw new ApiException(400, "BOTTOM 深度须恒为 " + d + " 米");
308	                }
309	            }
310	            case "ASCENT" -> {
311	                if (req.fromDepthM() != d || req.toDepthM() != 0) {
312	                    throw new ApiException(400, "ASCENT 深度须为 " + d + "→0 米");
313	                }
314	            }
315	            default -> throw new ApiException(400, "未知阶段 " + req.phase());
316	        }
317	    }
318	
319	    // ------------------------------------------------------------------
320	    // 4. 出水登记（进入 2 小时观察期）
321	    // ------------------------------------------------------------------
322	
323	    public IdempotencyService.Outcome<ApplyResult.SurfaceResult> surface(SurfaceRequest req) {
324	        requireDive(req.diveRequestId());
325	        Map<String, Object> fields = new LinkedHashMap<>();
326	        fields.put("diveRequestId", req.diveRequestId());
327	        fields.put("surfacedAt", req.surfacedAt() == null ? null : req.surfacedAt().toString());
328	
329	        return idempotency.execute(req.requestId(), "SURFACE", fields, () -> {
330	            DiveRow latest = requireDive(req.diveRequestId());
331	            if (!"DIVING".equals(latest.status())) {
332	                throw new ApiException(409,
333	                        "潜次处于 " + latest.status() + " 阶段，不能登记出水（须先成对执行）");
334	            }
335	            Instant surfacedAt = req.surfacedAt() != null ? req.surfacedAt() : Instant.now(clock);
336	            Instant now = Instant.now(clock);
337	            dives.markSurfaced(req.diveRequestId(), surfacedAt, "SURFACED", now);
338	            Instant due = surfacedAt.plus(OBSERVATION);
339	            return IdempotencyService.FirstResult.ok(new ApplyResult.SurfaceResult(
340	                    req.diveRequestId(), surfacedAt.toString(), due.toString(), "SURFACED", false));
341	        });
342	    }
343	
344	    // ------------------------------------------------------------------
345	    // 5. 观察期体征（有症状即加压舱预案并冻结；结案后迟到数据只记事件）
346	    // ------------------------------------------------------------------
347	
348	    public IdempotencyService.Outcome<ApplyResult.VitalsResult> vitals(VitalsRequest req) {
349	        requireDive(req.diveRequestId());
350	        Map<String, Object> fields = new LinkedHashMap<>();
351	        fields.put("diveRequestId", req.diveRequestId());
352	        fields.put("symptomatic", req.symptomatic());
353	        fields.put("observedAt", req.observedAt() == null ? null : req.observedAt().toString());
354	
355	        return idempotency.execute(req.requestId(), "SYMPTOM", fields, () -> {
356	            DiveRow dive = requireDive(req.diveRequestId());
357	            Instant now = Instant.now(clock);
358	            Instant observedAt = req.observedAt() != null ? req.observedAt() : now;
359	
360	            if ("CLOSED".equals(dive.status())) {
361	                // 结案为终态：迟到体征只记迟到事件，不改状态
362	                events.insert(req.diveRequestId(), EventTypes.LATE_VITALS,
363	                        "结案后迟到体征 symptomatic=" + req.symptomatic()
364	                                + " observedAt=" + observedAt, now);
365	                return IdempotencyService.FirstResult.ok(new ApplyResult.VitalsResult(
366	                        req.diveRequestId(), "CLOSED", req.symptomatic(), false, true, false));
367	            }
368	            if ("FROZEN".equals(dive.status())) {
369	                return IdempotencyService.FirstResult.ok(new ApplyResult.VitalsResult(
370	                        req.diveRequestId(), "FROZEN", true, true, false, false));
371	            }
372	            if (!"SURFACED".equals(dive.status())) {
373	                throw new ApiException(409, "潜次处于 " + dive.status() + " 阶段，尚在出水前，不能上报观察体征");
374	            }
375	            if (Boolean.TRUE.equals(req.symptomatic())) {
376	                dives.markSymptomatic(req.diveRequestId(), now);
377	                events.insert(req.diveRequestId(), EventTypes.CHAMBER_PROTOCOL,
378	                        "观察期出现症状，启动加压舱预案 observedAt=" + observedAt, now);
379	                return IdempotencyService.FirstResult.ok(new ApplyResult.VitalsResult(
380	                        req.diveRequestId(), "FROZEN", true, true, false, false));
381	            }
382	            return IdempotencyService.FirstResult.ok(new ApplyResult.VitalsResult(
383	                    req.diveRequestId(), "SURFACED", false, false, false, false));
384	        });
385	    }
386	
387	    // ------------------------------------------------------------------
388	    // 6. 结案（恰满 2 小时观察且无症状；终态；重复结案幂等成功；冻结态禁止结案）
389	    // ------------------------------------------------------------------
390	
391	    public IdempotencyService.Outcome<ApplyResult.CloseResult> close(CloseRequest req) {
392	        DiveRow dive = requireDive(req.diveRequestId());
393	        if ("CLOSED".equals(dive.status())) {
394	            // 结案终态：任何重复结案都返回幂等成功（即使换了操作 requestId）
395	            return new IdempotencyService.Outcome<>(new ApplyResult.CloseResult(
396	                    req.diveRequestId(), "CLOSED",
397	                    dive.closedAtUtc() == null ? null : dive.closedAtUtc().toString(),
398	                    true, true), 200, true);
399	        }
400	        if ("FROZEN".equals(dive.status())) {
401	            throw new ApiException(409, "观察期出现症状已启动加压舱预案，结案冻结");
402	        }
403	        if (!"SURFACED".equals(dive.status())) {
404	            throw new ApiException(409, "潜次处于 " + dive.status() + " 阶段，尚未出水观察，不能结案");
405	        }
406	        Instant closedAt = req.closedAt() != null ? req.closedAt() : Instant.now(clock);
407	        Instant earliest = dive.surfacedAtUtc().plus(OBSERVATION);
408	        if (closedAt.isBefore(earliest)) {
409	            long minutesLeft = Duration.between(closedAt, earliest).toMinutes();
410	            throw new ApiException(409, "观察期须恰满 2 小时无症状方可结案，还差约 "
411	                    + Math.max(1, minutesLeft) + " 分钟");
412	        }
413	        if (dive.symptomatic()) {
414	            throw new ApiException(409, "观察期出现症状，结案冻结");
415	        }
416	
417	        Map<String, Object> fields = new LinkedHashMap<>();
418	        fields.put("diveRequestId", req.diveRequestId());
419	        fields.put("closedAt", req.closedAt() == null ? null : req.closedAt().toString());
420	
421	        return idempotency.execute(req.requestId(), "CLOSE", fields, () -> {
422	            Instant now = Instant.now(clock);
423	            dives.markClosed(req.diveRequestId(), closedAt, now);
424	            return IdempotencyService.FirstResult.ok(new ApplyResult.CloseResult(
425	                    req.diveRequestId(), "CLOSED", closedAt.toString(), true, false));
426	        });
427	    }
428	
429	    // ------------------------------------------------------------------
430	    // 复算视图：剖面、速率告警、24 小时台账均可重算并与落库值核对
431	    // ------------------------------------------------------------------
432	
433	    public Map<String, Object> recompute(String diveRequestId) {
434	        DiveRow dive = requireDive(diveRequestId);
435	        Map<String, Object> view = new LinkedHashMap<>();
436	        view.put("requestId", dive.requestId());
437	        view.put("status", dive.status());
438	        view.put("teamKey", dive.teamKey());
439	        view.put("divers", List.of(dive.diverACode(), dive.diverBCode()));
440	        view.put("currentPlanVersion", dive.currentPlanVersion());
441	        view.put("surfacedAtUtc", dive.surfacedAtUtc() == null ? null
442	                : dive.surfacedAtUtc().toString());
443	        view.put("observationDueAtUtc", dive.surfacedAtUtc() == null ? null
444	                : dive.surfacedAtUtc().plus(OBSERVATION).toString());
445	        view.put("symptomatic", dive.symptomatic());
446	        view.put("closedAtUtc", dive.closedAtUtc() == null ? null
447	                : dive.closedAtUtc().toString());
448	
449	        List<Map<String, Object>> planViews = new ArrayList<>();
450	        for (PlanRow p : plans.findAll(diveRequestId)) {
451	            Map<String, Object> pv = new LinkedHashMap<>();
452	            pv.put("version", p.version());
453	            pv.put("depthM", p.depthM());
454	            pv.put("bottomMin", p.bottomMin());
455	            pv.put("ndlLimitMin", p.ndlLimitMin());
456	            pv.put("withinNdl", p.bottomMin() <= p.ndlLimitMin());
457	            pv.put("frozen", p.frozen());
458	            planViews.add(pv);
459	        }
460	        view.put("plans", planViews);
461	
462	        // 速率复算：深度差/历时与落库速率逐项核对
463	        List<Map<String, Object>> recordViews = new ArrayList<>();
464	        boolean allRatesConsistent = true;
465	        for (RecordRow r : records.findAllByDive(diveRequestId)) {
466	            BigDecimal recomputed = RecordRepository.rateOf(r.phase(), r.fromDepthM(),
467	                    r.toDepthM(), r.durationMin());
468	            boolean consistent = recomputed.compareTo(r.rateMMin()) == 0;
469	            allRatesConsistent &= consistent;
470	            Map<String, Object> rv = new LinkedHashMap<>();
471	            rv.put("id", r.id());
472	            rv.put("planVersion", r.planVersion());
473	            rv.put("diverCode", r.diverCode());
474	            rv.put("phase", r.phase());
475	            rv.put("fromDepthM", r.fromDepthM());
476	            rv.put("toDepthM", r.toDepthM());
477	            rv.put("durationMin", r.durationMin());
478	            rv.put("storedRateMMin", r.rateMMin().toPlainString());
479	            rv.put("recomputedRateMMin", recomputed.toPlainString());
480	            rv.put("rateConsistent", consistent);
481	            rv.put("effective", r.effective());
482	            rv.put("frozen", r.frozen());
483	            recordViews.add(rv);
484	        }
485	        view.put("records", recordViews);
486	        view.put("allRatesConsistent", allRatesConsistent);
487	
488	        view.put("alerts", alerts.findByDive(diveRequestId).stream().map(a -> {
489	            Map<String, Object> av = new LinkedHashMap<>();
490	            av.put("planVersion", a.planVersion());
491	            av.put("diverCode", a.diverCode());
492	            av.put("phase", a.phase());
493	            av.put("rateMMin", a.rateMMin().toPlainString());
494	            return av;
495	        }).toList());
496	
497	        // 台账复算：以每个生效 BOTTOM 事件时刻为窗口右端（含端点），重算 24 小时滚动累计
498	        List<Map<String, Object>> ledgerViews = new ArrayList<>();
499	        for (RecordRow r : records.findAllByDive(diveRequestId)) {
500	            if (!Phase.BOTTOM.name().equals(r.phase()) || !r.effective()) {
501	                continue;
502	            }
503	            Instant end = r.eventTimeUtc();
504	            List<LedgerRow> window = records.findLedgerWindowInclusive(r.diverCode(),
505	                    Timestamp.from(end.minus(Duration.ofHours(24))), Timestamp.from(end));
506	            int sum = window.stream().mapToInt(LedgerRow::bottomMin).sum();
507	            Map<String, Object> lv = new LinkedHashMap<>();
508	            lv.put("diverCode", r.diverCode());
509	            lv.put("eventTimeUtc", end.toString());
510	            lv.put("windowBottomMin", sum);
511	            lv.put("withinLimit", sum <= MAX_BOTTOM_MIN_24H);
512	            ledgerViews.add(lv);
513	        }
514	        view.put("cumulativeRecompute", ledgerViews);
515	
516	        view.put("events", events.findByDive(diveRequestId).stream().map(e -> {
517	            Map<String, Object> ev = new LinkedHashMap<>();
518	            ev.put("type", e.type());
519	            ev.put("payload", e.payload());
520	            ev.put("createdAtUtc", e.createdAtUtc().toString());
521	            return ev;
522	        }).toList());
523	        return view;
524	    }
525	
526	    private DiveRow requireDive(String requestId) {
527	        return dives.find(requestId).orElseThrow(() ->
528	                new ApiException(404, "潜次不存在: " + requestId));
529	    }
530	
531	    private static String teamKey(String a, String b) {
532	        return a.compareTo(b) <= 0 ? a + "|" + b : b + "|" + a;
533	    }
534	}
