        this.jdbc = jdbc;
    }

    /** 潜水员工号是否存在于合成名册。 */
    public boolean diverExists(String diverCode) {
        Integer count = jdbc.queryForObject(
                "SELECT COUNT(1) FROM diver WHERE diver_code = ?",
                Integer.class, diverCode);
