3	import org.junit.jupiter.api.Test;
4	
5	import java.time.Duration;
6	import java.time.Instant;
7	
8	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
9	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
10	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
11	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
12	
13	/**
14	 * 主流程与关键边界：恰免减压极限、速率恰 18、两人成组、观察恰满 2 小时、结案终态。
15	 */
16	class DiveWorkflowTest extends AbstractIntegrationTest {
17	
18	    private static final Instant T0 = Instant.parse("2026-09-25T00:00:00Z");
19	
20	    private String postJson(String uri, String json) throws Exception {
21	        return mockMvc.perform(post(uri).contentType("application/json").content(json))
22	                .andReturn().getResponse().getContentAsString();
23	    }
24	
25	    /** 完整合法潜次：18 米恰 50 分钟（恰 NDL）、速率恰 18、成对、观察恰满 2 小时结案。 */
26	    @Test
27	    void fullHappyFlow_exactLimits_closesAfterExactlyTwoHours() throws Exception {
28	        mockMvc.perform(post("/api/dives/apply").contentType("application/json")
29	                        .content(Requests.apply(objectMapper, "DIVE-1", "D001", "D002", 18, 50)))
30	                .andExpect(status().isCreated())
31	                .andExpect(jsonPath("$.status").value("APPLIED"))
32	                .andExpect(jsonPath("$.teamKey").value("D001|D002"));
33	
34	        // 恰免减压极限：18 米 NDL=50，底时间恰 50 合法
35	        mockMvc.perform(post("/api/dives/plans").contentType("application/json")
36	                        .content(Requests.plan(objectMapper, "PLAN-1", "DIVE-1", 18, 50)))
37	                .andExpect(status().isCreated())
38	                .andExpect(jsonPath("$.version").value(1))
39	                .andExpect(jsonPath("$.ndlLimitMin").value(50))
40	                .andExpect(jsonPath("$.replayed").value(false));
41	
42	        // 下潜 0→18 米历时 1 分钟，速率恰 18：单人不生效
43	        mockMvc.perform(post("/api/dives/records").contentType("application/json")
44	                        .content(Requests.record(objectMapper, "R-D1", "DIVE-1", "D001",
45	                                "DESCENT", 0, 18, 1, T0)))
46	                .andExpect(status().isOk())
47	                .andExpect(jsonPath("$.effective").value(false))
48	                .andExpect(jsonPath("$.pairedWith").doesNotExist());
49	        // 配对手成对生效，速率恰 18 不告警
50	        mockMvc.perform(post("/api/dives/records").contentType("application/json")
51	                        .content(Requests.record(objectMapper, "R-D2", "DIVE-1", "D002",
52	                                "DESCENT", 0, 18, 1, T0)))
53	                .andExpect(status().isOk())
54	                .andExpect(jsonPath("$.effective").value(true))
55	                .andExpect(jsonPath("$.pairedWith").value("D001"))
56	                .andExpect(jsonPath("$.speedAlert").value(false))
57	                .andExpect(jsonPath("$.rateMMin").value("18.00"));
58	
59	        // 水底成对 50 分钟，累计 50
60	        mockMvc.perform(post("/api/dives/records").contentType("application/json")
61	                        .content(Requests.record(objectMapper, "R-B1", "DIVE-1", "D001",
62	                                "BOTTOM", 18, 18, 50, T0.plusSeconds(60))))
63	                .andExpect(status().isOk()).andExpect(jsonPath("$.effective").value(false));
64	        mockMvc.perform(post("/api/dives/records").contentType("application/json")
65	                        .content(Requests.record(objectMapper, "R-B2", "DIVE-1", "D002",
66	                                "BOTTOM", 18, 18, 50, T0.plusSeconds(60))))
67	                .andExpect(status().isOk())
68	                .andExpect(jsonPath("$.effective").value(true))
69	                .andExpect(jsonPath("$.cumulativeBottomMin24h").value(50));
70	
71	        // 上升成对，速率恰 18
72	        mockMvc.perform(post("/api/dives/records").contentType("application/json")
73	                        .content(Requests.record(objectMapper, "R-A1", "DIVE-1", "D001",
74	                                "ASCENT", 18, 0, 1, T0.plusSeconds(60 * 51))))
75	                .andExpect(status().isOk());
76	        mockMvc.perform(post("/api/dives/records").contentType("application/json")
77	                        .content(Requests.record(objectMapper, "R-A2", "DIVE-1", "D002",
78	                                "ASCENT", 18, 0, 1, T0.plusSeconds(60 * 51))))
79	                .andExpect(status().isOk()).andExpect(jsonPath("$.speedAlert").value(false));
80	
81	        Instant surfaced = T0.plusSeconds(60 * 55);
82	        mockMvc.perform(post("/api/dives/surface").contentType("application/json")
83	                        .content(Requests.surface(objectMapper, "S-1", "DIVE-1", surfaced)))
84	                .andExpect(status().isOk())
85	                .andExpect(jsonPath("$.status").value("SURFACED"))
86	                .andExpect(jsonPath("$.observationDueAtUtc").value(surfaced.plus(Duration.ofHours(2)).toString()));
87	
88	        // 差 1 分钟不满 2 小时，禁止结案
89	        mockMvc.perform(post("/api/dives/close").contentType("application/json")
90	                        .content(Requests.close(objectMapper, "C-1", "DIVE-1",
91	                                surfaced.plus(Duration.ofHours(2)).minusSeconds(60))))
92	                .andExpect(status().isConflict());
93	
94	        // 恰满 2 小时结案
95	        mockMvc.perform(post("/api/dives/close").contentType("application/json")
96	                        .content(Requests.close(objectMapper, "C-1", "DIVE-1",
97	                                surfaced.plus(Duration.ofHours(2)))))
98	                .andExpect(status().isOk())
99	                .andExpect(jsonPath("$.status").value("CLOSED"))
100	                .andExpect(jsonPath("$.terminal").value(true));
101	
102	        // 复算视图：速率全部一致、无告警、台账在限内
103	        mockMvc.perform(get("/api/dives/DIVE-1/recompute"))
104	                .andExpect(status().isOk())
105	                .andExpect(jsonPath("$.allRatesConsistent").value(true))
106	                .andExpect(jsonPath("$.alerts.length()").value(0))
107	                .andExpect(jsonPath("$.cumulativeRecompute[0].withinLimit").value(true));
108	    }
109	
110	    /** 超过免减压极限 1 分钟 → 422，不出方案。 */
111	    @Test
112	    void exceedingNdlByOne_rejected() throws Exception {
113	        postJson("/api/dives/apply", Requests.apply(objectMapper, "DIVE-NDL", "D001", "D002", 18, 50));
114	        mockMvc.perform(post("/api/dives/plans").contentType("application/json")
115	                        .content(Requests.plan(objectMapper, "PLAN-NDL", "DIVE-NDL", 18, 51)))
116	                .andExpect(status().isUnprocessableEntity());
117	    }
118	
119	    /** 超速：24 米 1 分钟下潜速率 24＞18，成对后落告警并复算可见。 */
120	    @Test
121	    void overSpeedRaisesAlert_andSingleDiverRecordIneffective() throws Exception {
122	        postJson("/api/dives/apply", Requests.apply(objectMapper, "DIVE-SP", "D001", "D002", 24, 30));
123	        postJson("/api/dives/plans", Requests.plan(objectMapper, "PLAN-SP", "DIVE-SP", 24, 30));
124	
125	        // 仅 D001 单人超速下潜：不生效、无告警、无台账
126	        mockMvc.perform(post("/api/dives/records").contentType("application/json")
127	                        .content(Requests.record(objectMapper, "R-SP1", "DIVE-SP", "D001",
128	                                "DESCENT", 0, 24, 1, T0)))
129	                .andExpect(status().isOk())
130	                .andExpect(jsonPath("$.effective").value(false))
131	                .andExpect(jsonPath("$.speedAlert").value(false));
132	        org.junit.jupiter.api.Assertions.assertEquals(0,
133	                jdbc.queryForObject("SELECT COUNT(1) FROM speed_alert", Integer.class).intValue());
134	        org.junit.jupiter.api.Assertions.assertEquals(0,
135	                jdbc.queryForObject("SELECT COUNT(1) FROM bottom_time_ledger", Integer.class).intValue());
136	
137	        // 配对手（合规速率 12m/min）成对后，D001 的超速仍被复算告警
138	        mockMvc.perform(post("/api/dives/records").contentType("application/json")
139	                        .content(Requests.record(objectMapper, "R-SP2", "DIVE-SP", "D002",
140	                                "DESCENT", 0, 24, 2, T0)))
141	                .andExpect(status().isOk())
142	                .andExpect(jsonPath("$.effective").value(true));
143	        org.junit.jupiter.api.Assertions.assertEquals(1,
144	                jdbc.queryForObject("SELECT COUNT(1) FROM speed_alert WHERE diver_code='D001' "
145	                        + "AND rate_m_min > 18", Integer.class).intValue());
146	
147	        mockMvc.perform(get("/api/dives/DIVE-SP/recompute"))
148	                .andExpect(jsonPath("$.alerts[0].diverCode").value("D001"))
149	                .andExpect(jsonPath("$.alerts[0].rateMMin").value("24.00"));
150	    }
151	
152	    /** 同键重放返回首次结果；同键异参 409 且不改变潜次状态。 */
153	    @Test
154	    void sameKeyReplay_andConflictOnDifferentParams() throws Exception {
155	        String body = Requests.apply(objectMapper, "IDEM-1", "D001", "D002", 18, 50);
156	        mockMvc.perform(post("/api/dives/apply").contentType("application/json").content(body))
157	                .andExpect(status().isCreated()).andExpect(jsonPath("$.replayed").value(false));
158	        // 同键同参重放
159	        mockMvc.perform(post("/api/dives/apply").contentType("application/json").content(body))
160	                .andExpect(status().isCreated()).andExpect(jsonPath("$.replayed").value(true));
