165	        mockMvc.perform(post("/api/dives/apply").contentType("application/json")
166	                        .content(Requests.apply(objectMapper, "IDEM-1", "D001", "D002", 24, 30)))
167	                .andExpect(status().isConflict());
168	        org.junit.jupiter.api.Assertions.assertEquals(18,
