172	
173	    /** 观察期出现症状：启动加压舱预案、状态 FROZEN、结案被冻结。 */
174	    @Test
175	    void symptomFreezesClose_andStartsChamberProtocol() throws Exception {
176	        prepareDivingDive("DIVE-FZ", "D001", "D002", 18, 50, T0);
177	        Instant surfaced = T0.plusSeconds(60 * 55);
178	        postJson("/api/dives/surface", Requests.surface(objectMapper, "S-FZ", "DIVE-FZ", surfaced));
