180	        mockMvc.perform(post("/api/dives/vitals").contentType("application/json")
181	                        .content(Requests.vitals(objectMapper, "V-FZ", "DIVE-FZ", true,
182	                                surfaced.plusSeconds(60 * 30))))
183	                .andExpect(status().isOk())
184	                .andExpect(jsonPath("$.status").value("FROZEN"))
185	                .andExpect(jsonPath("$.chamberProtocolStarted").value(true));
