187	        mockMvc.perform(post("/api/dives/close").contentType("application/json")
188	                        .content(Requests.close(objectMapper, "C-FZ", "DIVE-FZ",
189	                                surfaced.plus(Duration.ofHours(3)))))
190	                .andExpect(status().isConflict());
191	        org.junit.jupiter.api.Assertions.assertEquals(1,
192	                eventRepository.countByType("DIVE-FZ", "CHAMBER_PROTOCOL"));
193	    }
194	
195	    /** 结案终态：重复结案幂等成功；结案后迟到体征只记迟到事件，状态不变。 */
196	    @Test
197	    void closedIsTerminal_repeatedCloseIdempotent_lateVitalsRecordedOnly() throws Exception {
198	        prepareDivingDive("DIVE-CL", "D001", "D002", 18, 50, T0);
199	        Instant surfaced = T0.plusSeconds(60 * 55);
200	        postJson("/api/dives/surface", Requests.surface(objectMapper, "S-CL", "DIVE-CL", surfaced));
201	        postJson("/api/dives/close", Requests.close(objectMapper, "C-CL", "DIVE-CL",
202	                surfaced.plus(Duration.ofHours(2))));
203	
204	        // 换一个操作 requestId 重复结案，仍幂等成功
205	        mockMvc.perform(post("/api/dives/close").contentType("application/json")
206	                        .content(Requests.close(objectMapper, "C-CL-2", "DIVE-CL",
207	                                surfaced.plus(Duration.ofHours(5)))))
