213	        mockMvc.perform(post("/api/dives/vitals").contentType("application/json")
214	                        .content(Requests.vitals(objectMapper, "V-LATE", "DIVE-CL", true,
215	                                surfaced.plus(Duration.ofHours(6)))))
216	                .andExpect(status().isOk())
