15	 * @param phase         DESCENT/BOTTOM/ASCENT
16	 * @param fromDepthM    起始深度，米
17	 * @param toDepthM      目标深度，米
18	 * @param durationMin   该段历时，分钟（正整数）
19	 * @param eventTime     该段作业时刻（UTC），用于速率、台账与 24 小时窗口复算
20	 */
21	public record RecordRequest(
22	        @NotBlank String requestId,
23	        @NotBlank String diveRequestId,
24	        @NotBlank String diverCode,
25	        @NotBlank String phase,
26	        @NotNull Integer fromDepthM,
27	        @NotNull Integer toDepthM,
28	        @Positive int durationMin,
29	        @NotNull Instant eventTime) {
30	
31	    /** 校验注解无法表达的跨字段规则。 */
32	    public void validate() {
33	        if (!"DESCENT".equals(phase) && !"BOTTOM".equals(phase) && !"ASCENT".equals(phase)) {
34	            throw new IllegalArgumentException("phase 必须为 DESCENT/BOTTOM/ASCENT");
35	        }
