    /** 旧/受控两条方案线互斥，旧潜次保持原语义。 */
    @Test
    void legacyAndControlledPlansAreExclusive_legacyKeepsOldSemantics() throws Exception {
        postJson("/api/dives/apply", Requests.apply(objectMapper, "LEG-1", "D003", "D004", 18, 50));
        postJson("/api/dives/plans", Requests.plan(objectMapper, "LGP-1", "LEG-1", 18, 50));
